def fixtures():
    image = {"architecture": "amd64", "os": "linux", "config": {
        "Env": ["NODE_ENV=production", "PORT=3001"],
        "Labels": {"org.opencontainers.image.revision": FIXTURE_MAIN_SHA,
                   "org.opencontainers.image.source": issuer.SOURCE_URL},
    }}
    config_raw = json.dumps(image, sort_keys=True, separators=(",", ":")).encode()
    config_digest = "sha256:" + hashlib.sha256(config_raw).hexdigest()
    raw_manifest = json.dumps({"schemaVersion": 2, "mediaType": "application/vnd.oci.image.manifest.v1+json",
                               "config": {"digest": config_digest, "mediaType": "application/vnd.oci.image.config.v1+json",
                                          "size": len(config_raw)}, "layers": []})
    platform_digest = "sha256:" + hashlib.sha256(raw_manifest.encode()).hexdigest()
    index_digest = "sha256:" + "a" * 64
    index = {
        "mediaType": "application/vnd.oci.image.index.v1+json", "digest": index_digest,
        "manifests": [
            {"mediaType": "application/vnd.oci.image.manifest.v1+json", "digest": platform_digest,
             "platform": {"architecture": "amd64", "os": "linux"}},
            {"digest": "sha256:" + "d" * 64, "platform": {"architecture": "unknown", "os": "unknown"},
             "annotations": {"vnd.docker.reference.type": "attestation-manifest",
                             "vnd.docker.reference.digest": platform_digest}},
        ],
    }
    provenance = {"SLSA": {
        "buildType": "https://mobyproject.org/buildkit@v1",
        "materials": [{"uri": "pkg:docker/node@22-alpine", "digest": {"sha256": "e" * 64}}],
        "invocation": {"configSource": {"entryPoint": issuer.PROVENANCE_DOCKERFILE},
                       "parameters": {"args": {"build-arg:" + key: value for key, value in issuer.BUILD_ARGS.items()}},
                       "environment": {"platform": issuer.PLATFORM}},
        "metadata": {issuer.METADATA_KEY: {
            "vcs": {"revision": FIXTURE_MAIN_SHA, "source": issuer.SOURCE_URL + ".git",
                    "localdir:context": ".", "localdir:dockerfile": "docker"},
            "source": {"infos": [{"filename": issuer.PROVENANCE_DOCKERFILE,
                                  "data": base64.b64encode(PINNED_DOCKERFILE).decode()}]},
        }},
    }}
    metadata = {"containerimage.digest": index_digest, "containerimage.config.digest": config_digest}
    return metadata, index, raw_manifest, image, provenance


class FakeGithub:
    def __init__(self):
        self.main = FIXTURE_MAIN_SHA
        self.tree_sha = "c" * 40
        self.calls = []
        self.tool = Path(issuer.__file__).read_bytes()
        self.bytes = {name: content.encode() for name, content in FROZEN_SOURCE_INPUTS.items()}

    def contents(self, name, raw):
        blob = hashlib.sha1(b"blob " + str(len(raw)).encode() + b"\0" + raw).hexdigest()
        return {"path": name, "type": "file", "encoding": "base64", "size": len(raw),
                "content": base64.b64encode(raw).decode(), "sha": blob}

    def responses(self, issuer_sha="f" * 40):
        tree = [{"path": name, "mode": "100644", "type": "blob",
                 "sha": self.contents(name, raw)["sha"]} for name, raw in self.bytes.items()]
        data = {"git/ref/heads/main": {"ref": "refs/heads/main", "object": {"type": "commit", "sha": self.main}},
                "git/commits/" + self.main: {"sha": self.main, "tree": {"sha": self.tree_sha}},
                "git/trees/" + self.tree_sha + "?recursive=1": {"sha": self.tree_sha, "truncated": False, "tree": tree},
                "contents/tools/ci/web_game_image.py?ref=" + issuer_sha: self.contents("tools/ci/web_game_image.py", self.tool)}
        for name, raw in self.bytes.items():
            data["contents/" + name + "?ref=" + self.main] = self.contents(name, raw)
        return data

    def read(self, path):
        self.calls.append(path)
        return copy.deepcopy(self.responses()[path])


class MainSourceAdmissionTest(unittest.TestCase):
    def setUp(self):
        self.github = FakeGithub()

    def admit(self, data=None, source=None, fingerprint=EXPECTED_INPUT_FINGERPRINT):
        data = self.github.responses() if data is None else data
        def read(path):
            value = data[path]
            if isinstance(value, list):
                return value.pop(0) if len(value) > 1 else value[0]
            return value
        return issuer.admit_source(source or self.github.main, fingerprint, read)

    def test_current_main_with_unchanged_reviewed_inputs_is_accepted(self):
        self.github.main = "1" * 40
        evidence = self.admit()
        self.assertEqual(evidence["source_sha"], "1" * 40)
        self.assertEqual(evidence["source_pins_sha256"], EXPECTED_INPUT_PINS)

    def test_unchanged_nine_inputs_do_not_admit_a_non_main_commit(self):
        # Keep every non-main commit/tree/blob response valid: removing only the
        # main equality gate must admit this fixture, rather than raise KeyError.
        other = FakeGithub()
        other.main = "a" * 40
        data = other.responses()
        data["git/ref/heads/main"]["object"]["sha"] = self.github.main
        with self.assertRaisesRegex(ValueError, "execution-time main"):
            self.admit(data, source=other.main)

    def test_all_nine_actual_byte_mutations_are_rejected(self):
        for name in SOURCE_INPUTS:
            raw = self.github.bytes[name]
            self.github.bytes[name] += b"changed"
            try:
                with self.subTest(path=name), self.assertRaisesRegex(ValueError, "input pins mismatch"):
                    self.admit()
            finally:
                self.github.bytes[name] = raw

    def test_forged_expected_fingerprint_cannot_repin_inputs(self):
        for value in ("0" * 64, EXPECTED_INPUT_FINGERPRINT.upper(), "main", ""):
            with self.subTest(value=value), self.assertRaisesRegex(ValueError, "fingerprint mismatch"):
                self.admit(fingerprint=value)

    def test_main_change_during_remote_input_audit_is_rejected(self):
        data = self.github.responses()
        before = data["git/ref/heads/main"]
        after = copy.deepcopy(before)
        after["object"]["sha"] = "b" * 40
        data["git/ref/heads/main"] = [before, after]
        with self.assertRaisesRegex(ValueError, "execution-time main"):
            self.admit(data)

    def test_ref_and_commit_shape_must_be_exact(self):
        for ref, kind, sha in (("refs/tags/main", "commit", FIXTURE_MAIN_SHA),
                               ("refs/heads/main", "tag", FIXTURE_MAIN_SHA),
                               ("refs/heads/main", "commit", "MAIN")):
            data = self.github.responses()
            data["git/ref/heads/main"] = {"ref": ref, "object": {"type": kind, "sha": sha}}
            with self.subTest(ref=ref, kind=kind), self.assertRaises(ValueError):
                self.admit(data)

    def test_missing_truncated_duplicate_or_symlink_tree_is_rejected(self):
        key = "git/trees/" + self.github.tree_sha + "?recursive=1"
        for kind in ("missing", "truncated", "duplicate", "symlink"):
            data = self.github.responses()
            tree = data[key]
            if kind == "missing": tree["tree"].pop()
            elif kind == "truncated": tree["truncated"] = True
            elif kind == "duplicate": tree["tree"].append(copy.deepcopy(tree["tree"][0]))
            else: tree["tree"][0]["mode"] = "120000"
            with self.subTest(kind=kind), self.assertRaises(ValueError):
                self.admit(data)

    def test_contents_path_encoding_size_and_blob_identity_are_checked(self):
        key = "contents/" + issuer.DOCKERFILE + "?ref=" + FIXTURE_MAIN_SHA
        for field, value in (("path", "elsewhere"), ("encoding", "raw"), ("content", "!invalid!"),
                             ("size", 999), ("sha", "b" * 40), ("type", "symlink")):
            data = self.github.responses()
            data[key][field] = value
            with self.subTest(field=field), self.assertRaises(ValueError):
                self.admit(data)

    def test_transport_fails_closed_without_echoing_tokens_or_response_body(self):
        import io
        import urllib.error
        marker = "private-credential-body"
        for failure in (urllib.error.HTTPError("https://api.github.com/", 302, marker, {}, None),
                        urllib.error.HTTPError("https://api.github.com/", 401, marker, {}, None),
                        urllib.error.HTTPError("https://api.github.com/", 429, marker, {}, None),
                        TimeoutError(marker), b'{"sha":"x","sha":"y"}', b'x' * (4 * 1024 * 1024 + 1),
                        b'not-json', b'[]'):
            opener = mock.Mock()
            if isinstance(failure, BaseException): opener.open.side_effect = failure
            else: opener.open.return_value = io.BytesIO(failure)
            with self.subTest(failure=type(failure).__name__), mock.patch.object(
                    issuer.urllib.request, "build_opener", return_value=opener):
                with self.assertRaises(ValueError) as caught:
                    issuer.read_github_json("git/ref/heads/main")
                self.assertEqual(str(caught.exception), "GitHub source read failed")
                self.assertNotIn(marker, str(caught.exception))
        self.assertIsNone(issuer.NoRedirect().redirect_request(None, None, 302, "", {}, "https://elsewhere/"))


class FakeCommands:
    def __init__(self):
        self.metadata, self.index, self.raw, self.image, self.provenance = fixtures()
        self.calls = []
        self.head = FIXTURE_MAIN_SHA
        self.status = ""
        self.extra_name = ""
        self.build_fails = False
        self.config_raw = json.dumps(self.image, sort_keys=True, separators=(",", ":")).encode()

    def read_blob(self, reference, size):
        descriptor = json.loads(self.raw)["config"]
        if reference != descriptor["digest"] or size != len(self.config_raw):
            raise AssertionError("fixture config blob reference mismatch")
        return self.config_raw

    def refresh_config(self):
        # Mutated runtime/label fixtures still reach their original guard with
        # internally valid content digests, not fabricated config IDs.
        raw = json.dumps(self.image, sort_keys=True, separators=(",", ":")).encode()
        if raw == self.config_raw:
            return
        manifest = json.loads(self.raw)
        old_config = manifest["config"]["digest"]
        actual_config = "sha256:" + hashlib.sha256(raw).hexdigest()
        manifest["config"].update(digest=actual_config, size=len(raw))
        self.config_raw = raw
        self.raw = json.dumps(manifest)
        platform = "sha256:" + hashlib.sha256(self.raw.encode()).hexdigest()
        self.index["manifests"][0]["digest"] = platform
        self.index["manifests"][1]["annotations"]["vnd.docker.reference.digest"] = platform
        if self.metadata.get("containerimage.config.digest") == old_config:
            self.metadata["containerimage.config.digest"] = actual_config

    def __call__(self, argv, cwd=None, env=None):
        self.calls.append((argv, cwd, env))
        if argv[:2] == ["git", "rev-parse"]:
            return self.head + "\n"
        if argv[:2] == ["git", "status"]:
            return self.status
        if argv[:2] == ["git", "ls-files"]:
            return issuer.DOCKERFILE + "\0" + self.extra_name
        if argv[:3] == ["docker", "buildx", "build"]:
            self.refresh_config()
            if self.build_fails:
                raise ValueError("synthetic build/publish failure")
            Path(argv[argv.index("--metadata-file") + 1]).write_text(json.dumps(self.metadata))
            return ""
        if argv[:4] == ["docker", "buildx", "imagetools", "inspect"]:
            if argv[-1] == "--raw":
                return self.raw
            return json.dumps({"{{json .Manifest}}": self.index, "{{json .Image}}": self.image,
                               "{{json .Provenance}}": self.provenance}[argv[-1]])
        raise AssertionError(f"unexpected command {argv}")


class ImageCandidateTest(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name) / "source"
        write_source_fixture(self.root)
        self.fake = FakeCommands()
        self.github = FakeGithub()
        patch = mock.patch.object(issuer, "read_github_json", self.github.read)
        patch.start()
        self.addCleanup(patch.stop)
        self.plan = issuer.make_plan(self.root, FIXTURE_MAIN_SHA, "f" * 40, "123", "1", self.fake)
        self.output = Path(self.temp.name) / "evidence"

    def issue(self):
        return issuer.issue(self.root, self.plan, self.output, self.fake, read_blob=self.fake.read_blob)

    def assert_rejected(self, message):
        with self.assertRaisesRegex(ValueError, message):
            self.issue()
        self.assertFalse((self.output / "candidate.json").exists())

    def test_valid_issue_keeps_digest_kinds_and_provenance(self):
        evidence = self.issue()
        self.assertEqual(evidence["status"], "VERIFIED_CANDIDATE")
        self.assertFalse(evidence["deployment_approved"])
        self.assertNotEqual(evidence["source_sha"], evidence["issuer_sha"])
        self.assertEqual(len({evidence[key] for key in ("index_digest", "platform_manifest_digest", "config_digest")}), 3)
        self.assertEqual(json.loads((self.output / "candidate.json").read_text()), evidence)
        builds = [call for call in self.fake.calls if call[0][:3] == ["docker", "buildx", "build"]]
        self.assertEqual(len(builds), 1)
        argv, cwd, env = builds[0]
        self.assertEqual(cwd, self.root)
        self.assertEqual(argv[argv.index("--platform") + 1], "linux/amd64")
        args = [argv[i + 1] for i, item in enumerate(argv) if item == "--build-arg"]
        self.assertEqual(set(args), {"ASSET_PREFIX=/game", "GATEWAY_WEB_URL=http://web-gateway:3000", "NEXT_PUBLIC_GATEWAY_URL=", "NEXT_PUBLIC_TOPDOWN_SCREENS=1"})
        self.assertIn("--provenance=mode=max,version=v0.2", argv)
        self.assertIn("--output=type=image,oci-mediatypes=true", argv)
        self.assertIn("--push", argv)
        self.assertEqual(env["BUILDX_GIT_CHECK_DIRTY"], "true")
        inspections = [call[0][4] for call in self.fake.calls if call[0][:4] == ["docker", "buildx", "imagetools", "inspect"]]
        self.assertTrue(all(ref.startswith(issuer.REPOSITORY + "@sha256:") for ref in inspections))

    def test_fixture_is_pinned_and_independent_of_moving_checkout_dockerfile(self):
        self.assertEqual(set(FROZEN_SOURCE_INPUTS), set(EXPECTED_INPUT_PINS))
        actual = {name: hashlib.sha256(content.encode()).hexdigest()
                  for name, content in FROZEN_SOURCE_INPUTS.items()}
        self.assertEqual(actual, EXPECTED_INPUT_PINS)
        self.assertEqual(issuer.SOURCE_INPUT_PINS, EXPECTED_INPUT_PINS)
        self.assertEqual(hashlib.sha256(PINNED_DOCKERFILE).hexdigest(), issuer.DOCKERFILE_SHA256)
        # An empty future checkout represents deletion/rename of every input file.
        future = Path(self.temp.name) / "future-checkout"
        future.mkdir()
        with mock.patch.object(sys.modules[__name__], "ROOT", future):
            source = Path(self.temp.name) / "independent-fixture"
            write_source_fixture(source)
            fake = FakeCommands()
            plan = issuer.make_plan(source, FIXTURE_MAIN_SHA, "f" * 40, "123", "1", fake)
            self.assertEqual(plan["source_pins_sha256"], EXPECTED_INPUT_PINS)
            evidence = issuer.issue(source, plan, self.output, fake, read_blob=fake.read_blob)
            self.assertEqual(evidence["status"], "VERIFIED_CANDIDATE")

    def test_source_contract_v3_binds_main_and_reviewed_nine_fingerprint(self):
        self.assertEqual(self.plan["source_contract_version"], 3)
        self.assertEqual(issuer.source_inputs_sha256(), EXPECTED_INPUT_FINGERPRINT)
        expected = {"version": 3, "source_sha": FIXTURE_MAIN_SHA,
                    "source_inputs_sha256": EXPECTED_INPUT_FINGERPRINT,
                    "source_pins_sha256": EXPECTED_INPUT_PINS,
                    "repository": issuer.REPOSITORY, "platform": issuer.PLATFORM,
                    "build_args": issuer.BUILD_ARGS, "flags": issuer.FLAGS}
        fingerprint = hashlib.sha256(json.dumps(expected, sort_keys=True,
                                                separators=(",", ":")).encode()).hexdigest()
        self.assertEqual(issuer.source_contract(FIXTURE_MAIN_SHA), expected)
        self.assertEqual(self.plan["source_contract_sha256"], fingerprint)


    def test_each_source_input_byte_change_rejected_before_push(self):
        for name in SOURCE_INPUTS:
            path = self.root / name
            original = path.read_bytes()
            try:
                path.write_bytes(original + b"\nchanged\n")
                with self.subTest(name=name), self.assertRaisesRegex(ValueError, "pin.*mismatch"):
                    self.issue()
                self.assertFalse(any(call[0][:3] == ["docker", "buildx", "build"]
                                     for call in self.fake.calls))
                self.assertFalse(self.output.exists())
            finally:
                path.write_bytes(original)

    def test_changed_next_config_pin_fails_before_push(self):
        path = self.root / "web/game/next.config.mjs"
        path.write_bytes(path.read_bytes() + b"\nchanged\n")
        self.assert_rejected("reviewed source input pins mismatch")
        self.assertFalse(self.output.exists())
        self.assertFalse(any(call[0][:3] == ["docker", "buildx", "build"]
                             for call in self.fake.calls))

