class WorkflowBoundaryTest(unittest.TestCase):
    def assert_no_failure_masking(self, workflow):
        self.assertNotIn("defaults", workflow, "workflow must use the default failing shell")
        for name, job in workflow["jobs"].items():
            self.assertNotIn("continue-on-error", job, f"{name} job must propagate failures")
            self.assertNotIn("defaults", job, f"{name} must use the default failing shell")
            for index, step in enumerate(job["steps"]):
                self.assertNotIn("continue-on-error", step, f"{name} step {index} must propagate failures")
                self.assertNotIn("shell", step, f"{name} step {index} cannot override the failing shell")
                if "run" in step:
                    self.assertNotRegex(step["run"], r"\|\|\s*true\b|\bset\s+\+e\b",
                                        f"{name} step {index} cannot mask command failures")
        self.assertNotIn("if", workflow["jobs"]["admit"]["steps"][0], "guard cannot be skipped")

    def test_admission_and_image_failures_cannot_be_masked(self):
        workflow = yaml.load(WORKFLOW.read_text(), Loader=yaml.BaseLoader)
        self.assert_no_failure_masking(workflow)

    def test_only_manual_github_hosted_image_job_with_pinned_actions(self):
        workflow = yaml.load(WORKFLOW.read_text(), Loader=yaml.BaseLoader)
        self.assert_no_failure_masking(workflow)
        self.assertEqual(set(workflow["on"]), {"workflow_dispatch"})
        inputs = workflow["on"]["workflow_dispatch"]["inputs"]
        self.assertEqual(set(inputs), {"expected_source_sha", "expected_issuer_sha", "expected_source_inputs_sha256"})
        self.assertEqual(inputs["expected_issuer_sha"]["required"], "true")
        self.assertNotIn("default", inputs["expected_issuer_sha"])
        for value in inputs.values():
            self.assertEqual(value["required"], "true")
            self.assertNotIn("default", value)
        self.assertEqual(workflow["permissions"], {"contents": "read"})
        self.assertEqual(set(workflow["jobs"]), {"admit", "image"})
        admission = workflow["jobs"]["admit"]
        self.assertEqual(admission["runs-on"], "ubuntu-24.04")
        self.assertEqual(admission["permissions"], {"contents": "read"})
        self.assertEqual(len(admission["steps"]), 1)
        self.assertNotIn("uses", admission["steps"][0])
        self.assertNotIn("${{", admission["steps"][0]["run"])
        self.assertNotRegex(admission["steps"][0]["run"], r"(?i)\b(docker|checkout|curl|gh|ssh|sudo)\b")
        job = workflow["jobs"]["image"]
        self.assertEqual(job["runs-on"], "ubuntu-24.04")
        self.assertEqual(job["permissions"], {"contents": "read", "packages": "write"})
        self.assertNotIn("environment", job)
        self.assertEqual(job["needs"], "admit")
        self.assertNotIn("if", job)
        self.assertEqual(job["env"], {"SOURCE_SHA": "${{ needs.admit.outputs.source_sha }}",
                                      "ISSUER_SHA": "${{ needs.admit.outputs.issuer_sha }}",
                                      "SOURCE_INPUTS_SHA256": "${{ needs.admit.outputs.source_inputs_sha256 }}",
                                      "ISSUER_TOOL_SHA256": "${{ needs.admit.outputs.issuer_tool_sha256 }}",
                                      "ADMISSION_EVIDENCE": "${{ needs.admit.outputs.admission_evidence }}",
                                      "GH_TOKEN": "${{ github.token }}", "PYTHONDONTWRITEBYTECODE": "1"})
        allowed = {
            "actions/checkout@11d5960a326750d5838078e36cf38b85af677262",
            "docker/setup-buildx-action@8d2750c68a42422c14e847fe6c8ac0403b4cbd6f",
            "docker/login-action@c94ce9fb468520275223c153574b00df6fe4bcc9",
            "actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02",
        }
        steps = job["steps"]
        self.assertEqual(len(steps), 8)
        for step in steps:
            if "uses" in step:
                self.assertIn(step["uses"], allowed)
            else:
                self.assertNotIn("${{", step["run"])
                self.assertNotRegex(step["run"], r"(?i)\b(ssh|gcloud|kubectl|curl|gh|sudo|compose|deploy)\b")
                self.assertIn("python3 issuer/tools/ci/web_game_image.py", step["run"])
        checkouts = [step for step in steps if step.get("uses", "").startswith("actions/checkout@")]
        self.assertEqual([step["with"]["path"] for step in checkouts], ["issuer", "source"])
        self.assertTrue(all(step["with"]["persist-credentials"] == "false" for step in checkouts))
        self.assertEqual(checkouts[0]["with"]["ref"], "${{ needs.admit.outputs.issuer_sha }}")
        self.assertEqual(checkouts[1]["with"]["ref"], "${{ needs.admit.outputs.source_sha }}")
        self.assertEqual(steps[1]["run"].split()[2], "validate-input")
        upload = steps[-1]
        self.assertNotIn("if", upload)
        self.assertEqual(upload["with"]["if-no-files-found"], "error")
        self.assertEqual(set(upload["with"]["path"].split()),
                         {"plan.json", "admission.json", "evidence/candidate.json", "evidence/build-metadata.json"})

    def run_admission(self, expected, actual, source=FIXTURE_MAIN_SHA,
                      fingerprint=EXPECTED_INPUT_FINGERPRINT, responses=None):
        workflow = yaml.load(WORKFLOW.read_text(), Loader=yaml.BaseLoader)
        self.assert_no_failure_masking(workflow)
        guard = workflow["jobs"]["admit"]["steps"][0]
        self.assertEqual(guard["env"], {
            "EXPECTED_ISSUER_SHA": "${{ inputs.expected_issuer_sha }}",
            "ACTUAL_ISSUER_SHA": "${{ github.workflow_sha }}",
            "SOURCE_SHA": "${{ inputs.expected_source_sha }}",
            "SOURCE_INPUTS_SHA256": "${{ inputs.expected_source_inputs_sha256 }}",
            "ACTUAL_REPOSITORY": "${{ github.repository }}", "GH_TOKEN": "${{ github.token }}",
        })
        with tempfile.TemporaryDirectory() as temp:
            output = Path(temp) / "outputs"
            datafile = Path(temp) / "api.json"
            datafile.write_text(json.dumps(responses if responses is not None else FakeGithub().responses()))
            env = {**os.environ, "EXPECTED_ISSUER_SHA": expected, "ACTUAL_ISSUER_SHA": actual,
                   "SOURCE_SHA": source, "SOURCE_INPUTS_SHA256": fingerprint,
                   "ACTUAL_REPOSITORY": "peppone-choi/opensamguk", "GH_TOKEN": "unit-readonly-token",
                   "GITHUB_OUTPUT": str(output), "UNIT_API_RESPONSES": str(datafile)}
            # Execute the actual guard in its failing shell; replace only HTTP transport.
            transport = """import io,json,os,urllib.request
responses=json.load(open(os.environ['UNIT_API_RESPONSES']))
class OfflineOpener:
    def open(self, request, timeout):
        path=request.full_url.removeprefix('https://api.github.com/repos/peppone-choi/opensamguk/')
        if path not in responses: raise OSError('unit-readonly-token')
        value=responses[path]
        if isinstance(value,dict) and '__error__' in value: raise OSError('unit-readonly-token')
        if isinstance(value,list):
            item=value.pop(0) if len(value)>1 else value[0]
        else: item=value
        return io.BytesIO(json.dumps(item).encode())
urllib.request.build_opener=lambda *args: OfflineOpener()
"""
            script = guard["run"].replace("python3 - <<'PY'\n", "python3 - <<'PY'\n" + transport, 1)
            result = subprocess.run(["bash", "-e", "-o", "pipefail", "-c", script],
                                    env=env, text=True, capture_output=True)
            outputs = output.read_text() if output.exists() else ""
            self.assertNotIn("unit-readonly-token", result.stdout + result.stderr)
            downstream = ["checkout", "login", "build/publish"] if result.returncode == 0 else []
            return result, outputs, downstream


    def test_approved_issuer_admission_outputs_bind_both_checkouts(self):
        result, outputs, downstream = self.run_admission("f" * 40, "f" * 40)
        self.assertEqual(result.returncode, 0, result.stderr)
        values = dict(line.split("=", 1) for line in outputs.splitlines())
        self.assertEqual(values["issuer_sha"], "f" * 40)
        self.assertEqual(values["source_sha"], FIXTURE_MAIN_SHA)
        self.assertEqual(values["source_inputs_sha256"], EXPECTED_INPUT_FINGERPRINT)
        proof = json.loads(values["admission_evidence"])
        self.assertEqual(proof["source_pins_sha256"], EXPECTED_INPUT_PINS)
        self.assertEqual(proof["issuer_tool_sha256"], values["issuer_tool_sha256"])
        self.assertEqual(values["issuer_tool_sha256"], hashlib.sha256(FakeGithub().tool).hexdigest())
        self.assertEqual(downstream, ["checkout", "login", "build/publish"])

    def test_wrong_full40_issuer_never_reaches_checkout_login_publish(self):
        result, outputs, downstream = self.run_admission("e" * 40, "f" * 40)
        self.assertNotEqual(result.returncode, 0)
        self.assertIn("differs from approved issuer", result.stderr)
        self.assertEqual(outputs, "")
        self.assertEqual(downstream, [])

    def test_missing_short_alias_uppercase_and_injected_issuer_rejected(self):
        for expected in ("", "abc123", "main", "F" * 40, "f" * 40 + ";echo injected"):
            with self.subTest(expected=expected):
                result, outputs, downstream = self.run_admission(expected, "f" * 40)
                self.assertNotEqual(result.returncode, 0)
                self.assertIn("lowercase full40", result.stderr)
                self.assertEqual(outputs, "")
                self.assertEqual(downstream, [])

    def test_invalid_actual_workflow_sha_rejected(self):
        result, outputs, downstream = self.run_admission("f" * 40, "main")
        self.assertNotEqual(result.returncode, 0)
        self.assertEqual(outputs, "")
        self.assertEqual(downstream, [])

    def test_source_admission_rejects_before_package_write_job(self):
        result, outputs, downstream = self.run_admission("f" * 40, "f" * 40, "a" * 40)
        self.assertNotEqual(result.returncode, 0)
        self.assertIn("current-main source or reviewed nine-input admission failed", result.stderr)
        self.assertEqual(outputs, "")
        self.assertEqual(downstream, [])

    def test_workflow_remote_byte_change_fingerprint_and_missing_read_are_rejected(self):
        github = FakeGithub()
        github.bytes["web/game/next.config.mjs"] += b"changed"
        changed = github.responses()
        missing = FakeGithub().responses()
        missing["git/ref/heads/main"] = {"__error__": True}
        malformed = FakeGithub().responses()
        malformed["contents/tools/ci/web_game_image.py?ref=" + "f" * 40]["sha"] = "0" * 40
        for responses, fingerprint in ((changed, EXPECTED_INPUT_FINGERPRINT),
                                       (missing, EXPECTED_INPUT_FINGERPRINT),
                                       (malformed, EXPECTED_INPUT_FINGERPRINT),
                                       (FakeGithub().responses(), "0" * 64)):
            result, outputs, downstream = self.run_admission("f" * 40, "f" * 40,
                                                            fingerprint=fingerprint, responses=responses)
            self.assertNotEqual(result.returncode, 0)
            self.assertEqual(outputs, "")
            self.assertEqual(downstream, [])

    def test_workflow_recheck_of_main_prevents_downstream_after_drift(self):
        responses = FakeGithub().responses()
        before = responses["git/ref/heads/main"]
        after = copy.deepcopy(before)
        after["object"]["sha"] = "b" * 40
        responses["git/ref/heads/main"] = [before, after]
        result, outputs, downstream = self.run_admission("f" * 40, "f" * 40, responses=responses)
        self.assertNotEqual(result.returncode, 0)
        self.assertEqual(outputs, "")
        self.assertEqual(downstream, [])


